def caesar_cipher(text: str, shift: int) -> str:
    result = ''
    for char in text:
        if char.isalpha():
            base = ord('A') if char.isupper() else ord('a')
            result += chr((ord(char) - base + shift) % 26 + base)
        else:
            result += char
    return result

def caesar_cipher(text: str, shift: int) -> str:
    result = []
    for c in text:
        if c.isupper():
            base = ord('A')
        elif c.islower():
            base = ord('a')
        else:
            result.append(c)
            continue
        offset = ord(c) - base
        new_offset = (offset + shift) % 26
        result.append(chr(base + new_offset))
    return ''.join(result)

def fibonacci(n: int) -> int:
    if n == 0:
        return 0
    elif n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        c = a + b
        a = b
        b = c
    return b

def flatten(lst: list) -> list:
    result = []
    for item in lst:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def is_palindrome(s: str) -> bool:
    processed = ''.join(c.lower() for c in s if c.isalnum())
    return processed == processed[::-1]

